// The widget profile's generated files, from packages/core/profile.json (the single source):
//   src/shared/profile-tables.ts     the tables the validator, the shim and the renderer enforce
//   docs/profile-v1.md               the profile for widget authors and client teams
//   docs/widget-runtime-profile.md   the authors' guide: only its "Out of the profile" list, between
//                                    <!-- profile:summary --> and <!-- /profile:summary -->, and the out list of its
//                                    agent block, between <!-- profile:agent --> and <!-- /profile:agent -->; the rest
//                                    is written by hand
//
//   corepack pnpm tsx packages/core/scripts/profile-build.ts           # write them
//   corepack pnpm tsx packages/core/scripts/profile-build.ts --check   # exit 1 when one is stale

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const pkgRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const root = path.resolve(pkgRoot, '..', '..');

export interface ProfileFeature {
  id: string;
  area: string;
  title: string;
  status: 'in' | 'out';
  decision: string;
  conditional?: boolean;
  neutralise?: string;
  note?: string;
  match?: Record<string, string[]>;
}
export interface ProfileFile {
  profile: number;
  frozen: string;
  decisions: Record<string, string>;
  tables: unknown;
  features: ProfileFeature[];
}

export function readProfile(): ProfileFile {
  return JSON.parse(fs.readFileSync(path.join(pkgRoot, 'profile.json'), 'utf8'));
}

export function tablesSource(p: ProfileFile): string {
  return `// Generated by packages/core/scripts/profile-build.ts from packages/core/profile.json. Do not edit:
// change profile.json and run \`corepack pnpm tsx packages/core/scripts/profile-build.ts\`.

/** The widget profile this framework build enforces (\`TelegramWidget.profile\`). */
export const PROFILE_VERSION = ${p.profile};

${Object.entries(p.tables as Record<string, unknown>).map(([k, v]) => `export const PROFILE_${constName(k)} = ${JSON.stringify(v, null, 1)} as const;\n`).join('\n')}
/** All of them (a bundle that imports one table alone gets only that one). */
export const PROFILE_TABLES = { ${Object.keys(p.tables as object).map((k) => `${k}: PROFILE_${constName(k)}`).join(', ')} };
`;
}

const constName = (k: string) => k.replace(/[A-Z]/g, (c) => '_' + c).toUpperCase();

const AREAS: [string, string][] = [
  ['html', 'HTML elements and attributes'], ['svg', 'Inline SVG'], ['css', 'CSS'], ['selector', 'Selectors'], ['at-rule', 'At-rules'],
  ['animation', 'Animation'], ['canvas', 'Canvas 2D'], ['js', 'JavaScript runtime'], ['sdk', 'TelegramWidget (SDK v1)'], ['input', 'Input'],
  ['limit', 'Limits'], ['behaviour', 'Client behaviour'],
];

const cell = (s: string) => s.replace(/\|/g, '\\|').replace(/\n/g, ' ');
const code = (list: readonly string[]) => list.map((s) => '`' + s + '`').join(', ');

export function docSource(p: ProfileFile): string {
  const t = p.tables as any;
  const counts = { in: 0, out: 0 };
  for (const f of p.features) counts[f.status]++;
  const out: string[] = [];
  out.push(`# Widget profile ${p.profile}`, '');
  out.push(`*Generated by \`packages/core/scripts/profile-build.ts\` from \`packages/core/profile.json\`; do not edit. Frozen ${p.frozen}: ${p.features.length} features, ${counts.in} in, ${counts.out} out.*`, '');
  out.push(
    'The profile is the contract between widgets and clients: a feature is **in** when every client draws it the same way, and every client\'s',
    'validator removes what is **out** before it reaches the renderer, so a widget looks the same on iOS, Android, macOS, desktop and the web.',
    'The validator (`packages/core/src/host/validator.ts`, `css-sanitizer.ts`), the Swift node model (`NativeValidator`), the sandbox shim and',
    'the renderer read their tables from this profile (`src/shared/profile-tables.ts`); `packages/conformance` checks a client against it.',
    '',
    '## Detecting the profile',
    '',
    `- \`TelegramWidget.profile\` is \`${p.profile}\`; \`TelegramWidget.isProfileAtLeast(n)\` is \`profile >= n\`. A later profile only adds features.`,
    '- `CSS.supports(property, value)` and `CSS.supports(condition)` answer from the profile: `true` only when the validator keeps the declaration as written.',
    '- `@supports` is evaluated by the validator against the same tables: the block is kept (unwrapped) or dropped before the CSS reaches the renderer.',
    '- A widget that checks nothing still loads; what is out is removed, as described in the tables below.',
    '',
  );
  out.push('## Decisions', '', '| key | decision |', '|---|---|');
  for (const [k, v] of Object.entries(p.decisions)) out.push(`| ${k} | ${cell(v)} |`);
  out.push('');
  // Every area gets a section: one without a title here is listed under its own name, never left out.
  for (const [area, title] of areasOf(p)) {
    const list = p.features.filter((f) => f.area === area);
    if (!list.length) continue;
    out.push(`## ${title}`, '', '| id | feature | status | when out | decision |', '|---|---|---|---|---|');
    for (const f of list) {
      const status = f.status === 'in' ? (f.conditional ? 'in (if every client draws it)' : 'in') : '**out**';
      out.push(`| \`${f.id}\` | ${cell(f.title)} | ${status} | ${cell(f.neutralise ?? '')} | ${f.decision} |`);
    }
    out.push('');
  }
  out.push('## Tables', '', 'What the validator lets through; anything else is removed as the features above say.', '');
  const html = t.html.elements as Record<string, string>;
  const by = (a: string) => Object.keys(html).filter((k) => html[k] === a).sort();
  out.push(`- **HTML elements kept:** ${code(by('keep'))}.`);
  out.push(`- **Rendered as \`<span>\`:** ${code(by('span'))}; **as \`<div>\`:** ${code(by('div'))}; unknown elements: \`<${t.html.unknown}>\`.`);
  out.push(`- **Dropped with their subtree:** ${code(by('drop'))}.`);
  out.push(`- **HTML attributes:** ${code(t.html.attributes)}, \`style\`, the URL attributes \`href\` and \`src\` (checked), and the prefixes ${code(t.html.attributePrefixes.map((x: string) => x + '*'))}.`);
  out.push(`- **SVG elements:** ${code(t.svg.elements)}.`);
  out.push(`- **SVG attributes:** ${code(t.svg.attributes)}, \`href\` (fragments only).`);
  out.push(`- **Image types (\`data:\` URLs):** ${code(t.images)}.`);
  out.push(`- **Events delivered to the widget:** ${code(t.events)}.`);
  out.push(`- **Element methods that reach the renderer:** ${code(t.methods)}; properties: ${code(t.properties)}.`);
  out.push(`- **Canvas methods:** ${code(t.canvas.methods)}; properties: ${code(t.canvas.properties)}; gradients: ${code(t.canvas.gradients)}; queries: ${code(t.canvas.queries)}.`);
  out.push(`- **CSS properties:** ${code(t.css.properties)}, and custom properties (\`--*\`).`);
  out.push(`- **CSS functions:** ${code(t.css.functions)} (\`url()\` takes \`data:\` images and \`#fragment\` only).`);
  out.push(`- **CSS units:** ${code(t.css.units)}, \`%\` and unitless numbers.`);
  for (const [prop, values] of Object.entries(t.css.values as Record<string, string[]>)) out.push(`- **\`${prop}\` values:** ${code(values)}.`);
  for (const [prop, map] of Object.entries(t.css.rewrite as Record<string, Record<string, string>>)) out.push(`- **\`${prop}\` rewritten:** ${Object.entries(map).map(([a, b]) => '`' + a + '` → `' + b + '`').join(', ')}.`);
  out.push(`- **Filter functions** (\`filter\`, \`backdrop-filter\`): ${code(t.css.filterFunctions)}; any other function is removed from the list.`);
  out.push(`- **3D transform functions (the declaration is dropped):** ${code(t.css.transform3d)}.`);
  out.push(`- **Font families:** ${code(t.css.fonts.generic)}; ${Object.entries(t.css.fonts.aliases as Record<string, string>).map(([a, b]) => '`' + a + '`').join(' and ')} (the vendor names of the system UI font) become \`system-ui\`, other names are removed from the list, ${Object.entries(t.css.fonts.fallback as Record<string, string>).map(([a, b]) => '`' + a + '` gets `' + b + '` after it').join(', ')}, an empty list becomes \`${t.css.fonts.default}\`.`);
  out.push(`- **Pseudo-classes:** ${code(t.css.pseudoClasses.map((x: string) => ':' + x))}; ${Object.entries(t.css.pseudoRewrite as Record<string, string>).map(([a, b]) => '`:' + a + '` becomes `' + b + '`').join(', ')}. **Pseudo-elements:** ${code(t.css.pseudoElements.map((x: string) => '::' + x))}. A selector with anything else is dropped from its list.`);
  out.push(`- **At-rules:** ${code(t.css.atRules.map((x: string) => '@' + x))}; nested rules are dropped.`);
  out.push(`- **The renderer's own stylesheet** (since v0.1.1 the defaults of the root and the text elements, with the bubble's palette \`--tg-theme-*\` and the client's text tokens \`--tg-text-*\`, and text not selectable unless the widget sets \`user-select: text\`; an unstyled \`<button>\` in the client's style, with the \`--tg-button-*\` tokens; any widget CSS wins over the layer, docs/sdk-v1.md §2.4): \`${t.uaStylesheet}\``);
  out.push(`- **Media types:** ${code(t.css.mediaTypes)}; **media features:** ${code(t.css.mediaFeatures)} (\`prefers-color-scheme\` and \`prefers-reduced-motion\` are answered by the client). A query with anything else drops its \`@media\` rule and makes \`matchMedia\` answer \`false\`.`);
  out.push('');
  return out.join('\n');
}

/** A feature's title without its explanations: every parenthesis without a colon goes ("overflow: auto / scroll
 *  (scrolling inside the widget)" → "overflow: auto / scroll"), one with a colon stays ("@media (hover: hover)"). */
export function briefTitle(title: string): string {
  return title.replace(/ \([^():]*\)/g, '').replace(/\|/g, '/');
}

function areasOf(p: ProfileFile): [string, string][] {
  return [...AREAS, ...[...new Set(p.features.map((f) => f.area))].filter((a) => !AREAS.some(([k]) => k === a)).map((a) => [a, a] as [string, string])];
}

/** The guide's list of what is out, one line per area (brief titles), with the counts. */
export function summarySource(p: ProfileFile): string {
  const counts = { in: 0, out: 0 };
  for (const f of p.features) counts[f.status]++;
  const out = [`*Generated from \`packages/core/profile.json\` (profile ${p.profile}): ${p.features.length} features, ${counts.in} in, ${counts.out} out; each one with how it is removed in \`docs/profile-v1.md\`.*`, ''];
  for (const [area, title] of areasOf(p)) {
    const list = p.features.filter((f) => f.area === area);
    if (!list.length) continue;
    const gone = list.filter((f) => f.status === 'out').map((f) => briefTitle(f.title).replace(/</g, '&lt;'));
    out.push(`- **${title}** (${list.length - gone.length} in, ${gone.length} out)${gone.length ? ': ' + gone.join(' · ') : ''}`);
  }
  return out.join('\n');
}

const AGENT_AREAS: Record<string, string> = { html: 'HTML', svg: 'SVG', css: 'CSS', selector: 'Selectors', 'at-rule': 'At-rules', animation: 'Animation', canvas: 'Canvas', js: 'JS', sdk: 'TelegramWidget', input: 'Input' };

/** The agent block's list of what is out: plain text for a model's system prompt, full titles, one line per area. */
export function agentOutSource(p: ProfileFile): string {
  const out: string[] = [];
  for (const [area, title] of areasOf(p)) {
    const gone = p.features.filter((f) => f.area === area && f.status === 'out').map((f) => f.title);
    if (gone.length) out.push(`- ${AGENT_AREAS[area] ?? title}: ${gone.join('; ')}.`);
  }
  return out.join('\n');
}

function replaceBetween(have: string, begin: string, end: string, body: string): string {
  const i = have.indexOf(begin), j = have.indexOf(end);
  if (i < 0 || j < i) throw new Error(`docs/widget-runtime-profile.md lost its ${begin} … ${end} markers`);
  return have.slice(0, i + begin.length) + '\n' + body + '\n' + have.slice(j);
}

/** `have` with its summary and agent out list replaced; the guide must keep all four markers. */
export function guideSource(p: ProfileFile, have: string): string {
  const withSummary = replaceBetween(have, '<!-- profile:summary -->', '<!-- /profile:summary -->', summarySource(p));
  return replaceBetween(withSummary, '<!-- profile:agent -->', '<!-- /profile:agent -->', agentOutSource(p));
}

const TARGETS: { file: string; make: (p: ProfileFile, have: string) => string }[] = [
  { file: path.join(pkgRoot, 'src', 'shared', 'profile-tables.ts'), make: tablesSource },
  { file: path.join(root, 'docs', 'profile-v1.md'), make: docSource },
  { file: path.join(root, 'docs', 'widget-runtime-profile.md'), make: guideSource },
];

if (process.argv[1] && path.resolve(process.argv[1]) === path.resolve(fileURLToPath(import.meta.url))) {
  const p = readProfile();
  const check = process.argv.includes('--check');
  let stale = 0;
  for (const t of TARGETS) {
    const have = fs.existsSync(t.file) ? fs.readFileSync(t.file, 'utf8') : '';
    const want = t.make(p, have);
    if (have === want) continue;
    if (check) { console.error(`stale: ${path.relative(root, t.file)}`); stale++; }
    else { fs.writeFileSync(t.file, want); console.log(`wrote ${path.relative(root, t.file)}`); }
  }
  if (stale) process.exit(1);
}
